import sys

def find_dominant_piranha(n, a):
    for i in range(1, n - 1):
        if a[i] > a[i - 1] and a[i] > a[i + 1]:
            return i + 1
    if a[0] > a[1]:
        return 1
    if a[n - 1] > a[n - 2]:
        return n
    return -1

input = sys.stdin.read().split()
t = int(input[0])
index = 1
results = []
for _ in range(t):
    n = int(input[index])
    a = list(map(int, input[index + 1:index + 1 + n]))
    results.append(find_dominant_piranha(n, a))
    index += 1 + n
print('\n'.join(map(str, results)))
